import React from "react";


export default function WeatherDay(props){
    function FormattedDay(){}
    function MaxTemp(){
        let temperature = props.data.daily[0].temperature.maximum;
        return Math.round(temperature);
    } 
    function MinTemp(){
        let temperature = props.data.daily[0].temperature.minimum;
        return Math.round(temperature);
    }



return (<div><div className="DailyWeatherDay">
            {props.data.daily[0].time}
                </div>
                <div className="DailyWeatherIcon"> <img src={props.data.daily[0].condition.icon_url}/></div>
                <div className="DailyWeatherTemperature">
                    <span className="max">{MaxTemp()}</span>
                    <span className="min">{MinTemp()}</span>
                </div></div>);}
